-- Content table `held_objective`: the QuestObjective rows of type 5 (a scripted objective,
-- done only by the server's 0x361) that the server leaves open because only an instance run
-- or a PvP match could complete them, loaded once at start into a persistent term
-- (genesis_prime/content) and never queried during play. It follows the pattern of
-- `tutorial_quest` (0031): `source`, `source_row` and `reason`, and the same checks.
--
-- Every other visible scripted objective with no marker, no creature linking it and no
-- optional flag is completed by the server once its quest's other required objectives are
-- done (genesis_prime/game/objective, `stand_in_scripts`); a row here is one it does not
-- complete. `kind` names why: 'instance_run' or 'pvp_match', a label for the later step
-- that gives the server that event and deletes the rows of its kind. The client has no rule
-- that says which objective needs an instance or a match: each row is the server's choice,
-- read from the objective's text and the quest's title, with the columns that agree
-- (QuestObjective flag 0x400, Quest2 questContentFinderTypeEnum 1 to 4) named in its reason.
-- The load checks each row against the client's tables (genesis_prime/game/held_objective).

create table held_objective (
  objective_id integer not null,
  kind text not null,
  source text not null,
  source_row integer,
  reason text,
  constraint held_objective_pkey primary key (objective_id),
  constraint held_objective_id_is_positive check (objective_id > 0),
  constraint held_objective_kind_is_known
    check (kind in ('instance_run', 'pvp_match')),
  constraint held_objective_source_is_a_content_source
    foreign key (source) references content_source (name),
  constraint held_objective_source_row_is_unique unique (source, source_row),
  constraint held_objective_source_row_is_positive check (source_row > 0),
  constraint held_objective_world_database_row_has_a_source_row
    check ((source = 'world_database') = (source_row is not null)),
  constraint held_objective_other_source_states_its_reason
    check (source = 'world_database' or reason is not null),
  constraint held_objective_reason_says_something
    check (reason is null or length(trim(reason)) > 0)
);

